function cardHTML(r, whyOverride) {
  const top5 = r.evidence.top_shipped.concat(r.evidence.best_review ? [r.evidence.best_review] : []);
  const prLinks = top5.slice(0, 3).map(p =>
    `<a href="${p.url}" target="_blank" rel="noopener">#${p.number}</a>`
  ).join('');
  const whyText = whyOverride || defaultWhy(r);
  return `
    <div class="card">
      <div class="rank">#${r.rank}</div>
      <div class="who">
        <div class="login">${r.login}</div>
        <div class="conf">${r.confidence.label} evidence — ${r.confidence.authored_prs} authored PR${r.confidence.authored_prs===1?'':'s'}, ${r.confidence.substantive_reviews} substantive review${r.confidence.substantive_reviews===1?'':'s'}</div>
        <div class="conf">${r.stats.merged_prs} merged PRs · ${r.stats.distinct_collaborators} collaborators${r.stats.median_hours_to_merge!=null ? ' · ' + Math.round(r.stats.median_hours_to_merge) + 'h median to merge' : ''}</div>
      </div>
      <div class="why">
        <div class="why-text">${whyText}</div>
        <div class="prs">${prLinks || '<span style="color:var(--text-muted);font-size:11.5px">no linked PR evidence</span>'}</div>
      </div>
      <div class="bars">
        <div class="score-row"><span style="font-size:11px;color:var(--text-muted)">Impact Score</span><span class="score-badge">${Math.round(r.impact_score)}</span></div>
        ${barRow('S', r.components.shipped_scope, 'var(--series-1)')}
        ${barRow('L', r.components.leverage_on_others, 'var(--series-2)')}
        ${barRow('O', r.components.ownership_trust, 'var(--series-3)')}
      </div>
    </div>`;
}

function barRow(label, value, color) {
  return `<div class="bar-row">
    <span class="bar-label">${label}</span>
    <span class="bar-track"><span class="bar-fill" style="width:${pct(value)}%;background:${color}"></span></span>
    <span class="bar-val">${Math.round(value)}</span>

