  --series-2:       #d95926;
  --series-3:       #199e70;
  --card-bg:        #1f1f1e;
  --code-bg:        #232322;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--page);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 15px;
  line-height: 1.6;
}
.wrap { max-width: 760px; margin: 0 auto; padding: 28px 24px 60px; }

.breadcrumb {
  font-size: 12.5px;
  color: var(--text-muted);
  margin-bottom: 18px;
}
.breadcrumb a { color: var(--text-muted); }
.breadcrumb a:hover { color: var(--series-1); }

.eyebrow {
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-bottom: 6px;
}
h1 { font-size: 26px; margin: 0 0 6px; letter-spacing: -0.01em; }
.subtitle { color: var(--text-secondary); font-size: 15px; margin: 0 0 28px; max-width: 640px; }

h2 { font-size: 18px; margin: 36px 0 10px; letter-spacing: -0.005em; }
h3 { font-size: 14.5px; margin: 22px 0 8px; color: var(--text-secondary); }
p { margin: 0 0 14px; color: var(--text-primary); }
.lede { font-size: 16px; color: var(--text-secondary); }
strong { color: var(--text-primary); }
code {
  font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  font-size: 0.88em;
  background: var(--code-bg);
  padding: 1px 5px;
  border-radius: 4px;
}
pre {
  background: var(--code-bg);
  border-radius: 8px;
  padding: 14px 16px;
  overflow-x: auto;
  font-size: 13px;
  line-height: 1.55;
}
pre code { background: none; padding: 0; }

.callout {
  border-left: 3px solid var(--series-1);
  background: var(--card-bg);
  border-radius: 0 8px 8px 0;
  padding: 12px 16px;
  margin: 18px 0;
  font-size: 14px;
  color: var(--text-secondary);
}
.callout strong { color: var(--text-primary); }
.callout.warn { border-left-color: var(--series-2); }
.callout.good { border-left-color: var(--series-3); }

table {
  width: 100%;
  border-collapse: collapse;
  margin: 14px 0 20px;
  font-size: 13.5px;
}
th, td {
  text-align: left;
  padding: 7px 10px;
  border-bottom: 1px solid var(--gridline);
}
th { color: var(--text-muted); font-weight: 600; font-size: 12px; text-transform: uppercase; letter-spacing: 0.02em; }
td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }
tr.total td { font-weight: 700; border-top: 1px solid var(--baseline); border-bottom: none; }

.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--text-secondary);
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 4px 10px;
  margin: 2px 6px 2px 0;
}
.dot { width: 8px; height: 8px; border-radius: 3px; display: inline-block; flex-shrink: 0; }

.card-nav {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin: 22px 0;
}
.card-nav a {
  display: block;
  border: 1px solid var(--border);
  background: var(--card-bg);
  border-radius: 10px;
  padding: 14px 16px;
  text-decoration: none;
  color: var(--text-primary);
}
.card-nav a:hover { border-color: var(--series-1); }
.card-nav .nav-weight { font-size: 11px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.03em; }
.card-nav .nav-title { font-size: 14.5px; font-weight: 600; margin: 3px 0 4px; }
.card-nav .nav-desc { font-size: 12.5px; color: var(--text-secondary); line-height: 1.4; }

footer.bottom {
  margin-top: 40px;
  padding-top: 16px;
  border-top: 1px solid var(--gridline);
  font-size: 12px;
  color: var(--text-muted);
}
footer.bottom a { color: var(--text-muted); }

a { color: var(--series-1); text-decoration: none; }
a:hover { text-decoration: underline; }

