281	
282	let currentData;
283	let activeMetric = 'overall';
284	const metricConfig = {
285	  overall: { label: 'Impact Score', value: r => r.impact_score },
286	  shipped: { label: 'Shipped', value: r => r.components.shipped_scope },
287	  review: { label: 'Review', value: r => r.components.leverage_on_others },
