308	      <div class="rank">#${displayRank}</div>
309	      <div class="who">
310	        <a class="login" href="https://github.com/${encodeURIComponent(r.login)}" target="_blank" rel="noopener" onclick="event.stopPropagation()">${escapeHTML(r.login)}</a>
311	        <div class="conf">${r.confidence.label} evidence — ${r.confidence.authored_prs} authored PR${r.confidence.authored_prs===1?'':'s'}, ${r.confidence.substantive_reviews} substantive review${r.confidence.substantive_reviews===1?'':'s'}</div>
